BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Evaluating opinion impact when misstatements are qualitatively significant
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Valley Distributors, the engagement team identifies $38,000 in uncorrected misstatements against overall materiality of $50,000. All misstatements involve revenue recognition timing differences that benefit management''s bonus targets. The CFO argues the misstatements are immaterial in aggregate. The engagement partner should:', '["Accept management''s position because the misstatements are below materiality", "Request management correct only the largest individual misstatement", "Consider the qualitative nature of the misstatements and their potential effect on the audit opinion", "Withdraw from the engagement due to management''s refusal to correct"]'::jsonb, 2, 'Under AU-C 450.11, the auditor must evaluate uncorrected misstatements individually and in aggregate, considering both quantitative amounts and qualitative factors such as the effect on management compensation arrangements. Because the misstatements systematically favor management''s bonus calculation, the qualitative characteristics may render them material despite being below the quantitative threshold. Choice A is incorrect because it ignores qualitative considerations required by AU-C 450.', 'hard', 4),

-- Q2: medium / L2 — Applying the clearly trivial threshold for accumulating misstatements
(1, 'Misstatements and Control Deficiencies', 'Redwood Analytics Inc. has overall materiality set at $100,000 and performance materiality at $75,000. The auditor establishes the clearly trivial threshold at $5,000. During testing, the auditor identifies a $3,200 misstatement in prepaid expenses. Under AU-C 450, the auditor should:', '["Accumulate the misstatement for aggregate evaluation at the end of the audit", "Disregard the misstatement because it falls below the clearly trivial threshold", "Report the misstatement to those charged with governance immediately", "Adjust performance materiality downward to capture the misstatement"]'::jsonb, 1, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial, meaning amounts clearly inconsequential both individually and in aggregate. Because the $3,200 misstatement falls below the $5,000 clearly trivial threshold, the auditor is not required to accumulate it. Choice A is incorrect because accumulation is required only for misstatements that exceed the clearly trivial threshold, not those below it.', 'medium', 2),

-- Q3: medium / L2 — Projecting sample misstatements to the population
(1, 'Misstatements and Control Deficiencies', 'Pineview Construction Corp. has 800 vendor invoices totaling $4,200,000. The auditor samples 40 invoices and finds pricing errors totaling $12,600 in the sample, which represents $520,000 in tested value. The auditor should project the misstatement to the population as approximately:', '["$101,769 by applying the sample error rate to the total population value", "$252,000 by multiplying the error amount by the number of untested invoices", "$12,600 because projection is unnecessary when the sample error is below materiality", "$50,400 by multiplying the sample error by the ratio of population to sample size"]'::jsonb, 0, 'Under AU-C 530.13, when errors are found in a sample, the auditor must project the misstatement to the population. The projected misstatement is calculated as ($12,600 / $520,000) x $4,200,000 = approximately $101,769, using the tainting percentage approach. Choice D is incorrect because it uses item count rather than dollar value, which does not properly weight the projection for variable sampling methods.', 'medium', 2),

-- Q4: hard / L4 — Qualitative factors when misstatement affects regulatory compliance
(1, 'Misstatements and Control Deficiencies', 'Sterling Financial Group is a broker-dealer subject to SEC net capital requirements. During the audit, the engagement team identifies an uncorrected $28,000 overstatement of net capital. Overall materiality is $200,000. However, correcting the misstatement would cause Sterling to fall below its minimum net capital requirement by $3,000. The auditor should recommend:', '["No opinion modification because the misstatement is clearly below materiality", "Disclosure of the deficiency in an emphasis-of-matter paragraph only", "Adjusting the audit report to include an other-matter paragraph about regulatory compliance", "That management correct the misstatement, as its qualitative significance outweighs its quantitative immateriality"]'::jsonb, 3, 'Under AU-C 450.A16, misstatements that may affect regulatory compliance constitute qualitatively material misstatements regardless of their quantitative size. Because correcting the $28,000 error would cause Sterling to violate SEC net capital requirements, the misstatement has significant qualitative implications making it effectively material. Choice A is incorrect because AU-C 450 requires the auditor to consider qualitative factors beyond the numerical materiality threshold when evaluating misstatements.', 'hard', 4),

-- Q5: easy / L1 — Definition of clearly trivial under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term ''clearly trivial'' mean regarding identified misstatements?', '["Amounts that are clearly inconsequential, whether taken individually or in the aggregate", "Any misstatement below 1% of total assets", "Misstatements that management has agreed to correct before year-end", "Errors discovered in accounts that are not material to the financial statements"]'::jsonb, 0, 'Under AU-C 450.05, clearly trivial describes misstatements that are clearly inconsequential both individually and in aggregate. The auditor is not required to accumulate these for evaluation. The standard does not prescribe a specific percentage threshold. Choice B is incorrect because AU-C 450 does not define clearly trivial using a fixed percentage; rather, it is a matter of professional judgment.', 'easy', 1),

-- Q6: easy / L1 — Design deficiency versus operating deficiency distinction
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what distinguishes a deficiency in design from a deficiency in operation?', '["A design deficiency involves employee errors, while an operating deficiency involves missing controls", "A design deficiency occurs during planning, while an operating deficiency occurs during fieldwork", "A design deficiency exists when a control is missing or improperly designed, while an operating deficiency exists when a properly designed control does not operate effectively", "A design deficiency affects financial statements, while an operating deficiency affects only internal reports"]'::jsonb, 2, 'Under AU-C 265.07, a deficiency in design exists when a necessary control is missing or not properly designed to meet the control objective. A deficiency in operation exists when a properly designed control does not operate as designed or the person performing it lacks the authority or competence. Choice A is incorrect because employee errors relate to operating deficiencies, not the defining characteristic of either type.', 'easy', 1),

-- Q7: medium / L3 — Fraud-related misstatement elevating control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Supply Co., the auditor discovers that an accounts payable clerk created a fictitious vendor and processed $18,000 in fraudulent payments over six months. The fraud was detected only because of an anonymous tip, not through any existing control. Management''s materiality is $250,000. The auditor should most likely assess this control deficiency as:', '["A deficiency in operation because the existing controls failed to prevent the fraud", "A material weakness because the absence of a control that could detect or prevent fraud indicates a reasonable possibility of material misstatement", "A significant deficiency because the actual misstatement was well below materiality", "Not a reportable condition because the fraud was ultimately detected and corrected"]'::jsonb, 1, 'Under AU-C 265.A12, fraud committed by employees that is not detected by internal controls is a strong indicator of a material weakness. Even though the $18,000 actual loss was below materiality, the absence of preventive or detective controls over fictitious vendors means the same scheme could have continued at much larger amounts. Choice C is incorrect because severity is based on the potential magnitude of misstatement the deficiency could cause, not the actual amount of the identified fraud.', 'medium', 3),

-- Q8: medium / L3 — Segregation of duties weakness cascading across cycles
(1, 'Misstatements and Control Deficiencies', 'At Briarwood Retail Group, the same employee records inventory receipts, enters vendor invoices, and authorizes payments. The auditor identifies that this lack of segregation of duties affects both the inventory and accounts payable cycles. When evaluating this deficiency under AU-C 265, the auditor should analyze:', '["Only the accounts payable cycle because that is where the payment authorization risk is highest", "Each cycle independently without considering the combined effect", "The deficiency only if actual misstatements have been detected in both cycles", "The combined magnitude of potential misstatements across all affected financial statement accounts"]'::jsonb, 3, 'Under AU-C 265.A8, when evaluating severity, the auditor considers the financial statement amounts exposed to the deficiency. Because the lack of segregation of duties affects both inventory and accounts payable, the auditor must consider the combined potential misstatement across all affected accounts. Choice B is incorrect because AU-C 265 requires the auditor to evaluate the combined effect of deficiencies that share a common cause rather than assessing them in isolation.', 'medium', 3),

-- Q9: easy / L1 — Definition of tolerable misstatement in audit sampling
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 530, what is the purpose of tolerable misstatement in audit sampling?', '["It is the maximum misstatement in a population that the auditor can accept and still conclude the sample results support the audit objective", "It is the total amount of all detected misstatements during testing", "It is the threshold below which individual misstatements need not be reported to management", "It is the amount by which actual misstatements exceed expected misstatements"]'::jsonb, 0, 'Under AU-C 530.05, tolerable misstatement is a monetary amount set by the auditor representing the maximum misstatement in a population that the auditor is willing to accept. It is typically set at or below performance materiality. Choice B is incorrect because the total of detected misstatements describes the aggregate of identified errors, not the pre-established acceptance threshold used in designing the sampling application.', 'easy', 1),

-- Q10: medium / L2 — Misstatement accumulation documentation requirements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestline Technologies Inc., the engagement team identifies 14 misstatements exceeding the clearly trivial threshold of $2,000. Management corrects 10 of the misstatements and declines to adjust the remaining four, which total $31,000. Under AU-C 450, the auditor''s documentation of misstatements should include:', '["Only the four uncorrected misstatements because corrected items no longer affect the financial statements", "Only misstatements exceeding performance materiality", "All 14 accumulated misstatements, the basis for evaluation, and whether uncorrected misstatements are material individually or in aggregate", "A summary total of all misstatements without individual details"]'::jsonb, 2, 'Under AU-C 450.14, the auditor must document all accumulated misstatements during the audit, whether uncorrected misstatements are material individually or in aggregate, and the basis for that evaluation. Corrected misstatements are documented because they may indicate systemic issues. Choice A is incorrect because AU-C 450 requires documentation of all accumulated misstatements, including those management corrected, to provide a complete audit record.', 'medium', 2),

-- Q11: easy / L2 — Classifying a specific scenario as an operating deficiency
(1, 'Misstatements and Control Deficiencies', 'Lakeshore Medical Billing has a policy requiring supervisory review of all insurance claims over $10,000 before submission. During testing, the auditor finds that the supervisor approved 45 of 50 sampled claims without reviewing the supporting documentation. This situation is best classified as:', '["A design deficiency because the $10,000 threshold is set too high", "A deficiency in operation because a properly designed control is not being performed effectively", "A significant deficiency that requires immediate management correction", "An acceptable deviation within normal sampling tolerances"]'::jsonb, 1, 'Under AU-C 265.07, a deficiency in operation exists when a properly designed control does not operate as intended or the person performing it lacks competence or authority. The review policy is appropriately designed, but the supervisor is not performing the review effectively. Choice A is incorrect because the control''s design is reasonable; the problem is that the supervisor approves claims without reviewing the supporting documentation.', 'easy', 2),

-- Q12: easy / L1 — Restriction on communicating control deficiencies externally
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom should the auditor''s written communication of significant deficiencies and material weaknesses NOT be directed?', '["The audit committee of the board of directors", "The entity''s chief executive officer", "The board of directors in the absence of an audit committee", "External regulatory agencies without management''s knowledge or consent"]'::jsonb, 3, 'Under AU-C 265.12, the auditor communicates significant deficiencies and material weaknesses in writing to those charged with governance, typically the audit committee or the full board. The standard does not authorize the auditor to unilaterally report control deficiencies to external regulators without management''s knowledge unless required by law. Choice A is incorrect because the audit committee is the primary intended recipient of such written communications.', 'easy', 1),

-- Q13: medium / L2 — Timing deadline for written communication of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Northgate Properties LLC has a December 31 fiscal year-end. The audit report is released on March 15, 2026. The auditor identified two significant deficiencies and one material weakness during the engagement. Under AU-C 265, the written communication of these control deficiencies must be issued no later than:', '["May 14, 2026, which is 60 days after the report release date", "December 31, 2025, the fiscal year-end date", "March 15, 2026, the date the audit report is released", "January 15, 2026, within 15 days of year-end"]'::jsonb, 0, 'Under AU-C 265.13, the auditor''s written communication of significant deficiencies and material weaknesses must be made no later than 60 days following the report release date. Since the report was released March 15, 2026, the deadline is May 14, 2026. Choice C is incorrect because while the auditor may communicate on the report release date, AU-C 265 provides a 60-day window following that date.', 'medium', 2),

-- Q14: hard / L4 — Evaluating whether to re-communicate a recurring material weakness
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Brookfield Hospitality Group, the engagement team identifies that a material weakness in the cash disbursement process — first reported during the 2023 audit and again in 2024 — remains unremediated. Management acknowledges the weakness but cites budget constraints. The engagement partner should evaluate whether to:', '["Omit the material weakness from the current year communication because it was previously reported", "Downgrade the material weakness to a significant deficiency due to management''s ongoing awareness", "Re-communicate the material weakness in writing, noting that it was previously communicated and remains unremediated", "Issue an adverse opinion solely because the material weakness has persisted for three years"]'::jsonb, 2, 'Under AU-C 265.A18, if a previously communicated significant deficiency or material weakness remains unremediated, the auditor should re-communicate it in the current period. The standard permits referencing prior communications. Unremediated weaknesses do not lose their significance merely because management is aware of them. Choice A is incorrect because AU-C 265 does not exempt previously reported deficiencies from re-communication; the condition persists regardless of prior reporting.', 'hard', 4),

-- Q15: hard / L4 — Judging whether remediation of a material weakness is sufficient
(1, 'Misstatements and Control Deficiencies', 'Oakmont Financial Services reported a material weakness in its loan loss reserve estimation process during the 2024 audit. In 2025, management implemented new estimation software and hired an experienced credit analyst. The auditor tests the new process and finds estimates are now within an acceptable range, but the credit analyst has been in the role for only two months and the software configuration has not been independently validated. The auditor should:', '["Conclude the material weakness is remediated because the estimation results are accurate", "Evaluate whether the new controls have operated for a sufficient period and been adequately tested before concluding remediation", "Report a new significant deficiency related to the software validation gap while removing the original material weakness", "Defer evaluation of remediation until the following audit year when more operating history is available"]'::jsonb, 1, 'Under AU-C 265.A15, remediation requires that the new or revised control operates for a sufficient period and the auditor has tested its operating effectiveness. Two months of operation and untested software configuration are insufficient to conclude remediation. Accurate results alone do not confirm the control is operating effectively on a sustained basis. Choice A is incorrect because AU-C 265 requires evidence of both proper design and effective operation over an adequate period.', 'hard', 4),

-- Q16: medium / L3 — Analyzing how identified misstatements affect further audit procedures
(1, 'Misstatements and Control Deficiencies', 'While testing accounts receivable at Fernwood Electronics, the auditor finds misstatements totaling $45,000 in a sample representing $800,000 of the $3,200,000 receivable balance. Performance materiality is $60,000. The auditor should analyze this finding by recognizing that:', '["The projected misstatement likely exceeds performance materiality, requiring expanded testing or alternative procedures for the untested portion", "No additional procedures are needed because the actual misstatements found are below performance materiality", "The receivable balance should be written down by $45,000 without further testing", "Only the specific invoices containing errors need correction, with no population-level implications"]'::jsonb, 0, 'Under AU-C 530.13, misstatements found in a sample must be projected to the population. Projecting the $45,000 error across the $3,200,000 balance yields approximately $180,000, which far exceeds the $60,000 performance materiality, requiring the auditor to expand testing or perform alternative procedures. Choice B is incorrect because the relevant comparison is between the projected misstatement and performance materiality, not between the raw sample misstatement and performance materiality.', 'medium', 3),

-- Q17: medium / L3 — Indicators of management bias in misstatement patterns
(1, 'Misstatements and Control Deficiencies', 'During the audit of Grandview Holdings, the engagement team notices that all 11 uncorrected misstatements identified across various accounts consistently overstate net income by small amounts, each individually below 10% of materiality. None of the misstatements overstate expenses or understate revenue. This pattern most likely indicates:', '["Random sampling error that does not require further investigation", "A need to increase the sample size for additional testing", "An acceptable outcome because each individual misstatement is clearly trivial", "Possible management bias that the auditor should evaluate under AU-C 450 when assessing the aggregate effect of uncorrected misstatements"]'::jsonb, 3, 'Under AU-C 450.A13, the auditor evaluates whether uncorrected misstatements indicate possible bias when they consistently move in the same direction. An income-increasing pattern across all 11 items suggests intentional or systematic bias rather than random error, affecting the aggregate materiality assessment. Choice A is incorrect because a unidirectional pattern across multiple accounts is unlikely to result from random error and warrants evaluation for management bias.', 'medium', 3),

-- Q18: hard / L4 — Pervasive control deficiencies and potential disclaimer of opinion
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summitview Manufacturing, the engagement team identifies material weaknesses in revenue recognition, inventory valuation, and accounts payable — three of the five major transaction cycles. Management lacks resources to remediate any deficiencies before year-end and restricts the auditor''s access to certain supporting documents. The engagement partner must evaluate whether these combined circumstances warrant:', '["A qualified opinion for the specific accounts affected by the material weaknesses", "An unmodified opinion with an emphasis-of-matter paragraph about the control environment", "A disclaimer of opinion if the combined effect of the pervasive deficiencies and scope limitation prevents obtaining sufficient appropriate audit evidence", "Withdrawal from the engagement without issuing any opinion"]'::jsonb, 2, 'Under AU-C 705.10, when the auditor is unable to obtain sufficient appropriate audit evidence and the possible effects are both material and pervasive, a disclaimer of opinion is appropriate. Material weaknesses across three of five major cycles combined with restricted document access may prevent forming an opinion. Choice A is incorrect because a qualified opinion applies when misstatements or scope limitations are material but not pervasive; deficiencies across multiple major cycles suggests pervasiveness.', 'hard', 4),

-- Q19: easy / L1 — Content of management representation regarding uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what must the auditor request from management regarding uncorrected misstatements?', '["A signed acknowledgment that the external auditors have no further responsibility", "A written representation that management believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole", "An oral statement confirming agreement with the auditor''s materiality assessment", "A revised set of financial statements excluding all uncorrected amounts"]'::jsonb, 1, 'Under AU-C 450.14, the auditor requests that management provide a written representation stating it believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. A summary of such items is included in or attached to the representation. Choice C is incorrect because AU-C 450 specifically requires written, not oral, representations from management.', 'easy', 1),

-- Q20: medium / L3 — Selective correction pattern suggesting management bias
(1, 'Misstatements and Control Deficiencies', 'Ridgeline Corporation''s management corrects all identified misstatements that decrease net income but declines to correct four misstatements totaling $22,000 that increase net income. Materiality is $75,000. When evaluating the remaining uncorrected misstatements, the auditor should consider that:', '["Management''s selective correction pattern suggests possible bias, requiring the auditor to reassess whether the uncorrected misstatements are material after considering this qualitative factor", "The uncorrected misstatements are acceptable because they fall well below materiality", "The auditor must correct the misstatements independently of management''s decisions", "Management''s correction of some misstatements demonstrates good faith and eliminates bias concerns"]'::jsonb, 0, 'Under AU-C 450.A13, the auditor considers whether the pattern of uncorrected misstatements indicates possible management bias. Selectively correcting only income-decreasing misstatements while leaving income-increasing ones uncorrected is a strong indicator of bias that could affect the overall materiality assessment. Choice D is incorrect because correcting some misstatements does not negate bias concerns when the pattern of corrections consistently favors a particular financial outcome.', 'medium', 3),

-- Q21: medium / L2 — Management representation letter requirement for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Whitfield Consulting Group, the auditor accumulates uncorrected misstatements totaling $17,500 against materiality of $80,000. Management declines to adjust the financial statements. Under AU-C 580, the management representation letter should include:', '["A statement that management has corrected all identified misstatements", "Only the aggregate dollar amount of uncorrected misstatements", "A certification that all possible misstatements have been identified and disclosed", "Management''s acknowledgment that uncorrected misstatements are immaterial, with the summary of misstatements attached"]'::jsonb, 3, 'Under AU-C 580.16, the management representation letter must include management''s acknowledgment that the effects of uncorrected misstatements aggregated by the auditor are immaterial, both individually and in aggregate, to the financial statements as a whole. The summary is attached to the letter. Choice B is incorrect because the representation requires more than a dollar amount — it requires management''s explicit assertion about immateriality plus the detailed summary.', 'medium', 2),

-- Q22: medium / L2 — Opinion modification when aggregate misstatements exceed materiality
(1, 'Misstatements and Control Deficiencies', 'At Blackstone Environmental Services, the auditor identifies aggregate uncorrected misstatements of $165,000. Overall materiality is $150,000. Management refuses to adjust the financial statements, stating the misstatements involve legitimate professional judgment differences. Under AU-C 705, the auditor should:', '["Issue an unmodified opinion with an other-matter paragraph disclosing the disagreement", "Issue a qualified or adverse opinion depending on whether the misstatements are pervasive", "Accept management''s judgment and issue an unmodified opinion", "Withdraw from the engagement without issuing a report"]'::jsonb, 1, 'Under AU-C 705.08, when uncorrected misstatements are material to the financial statements and management refuses to correct them, the auditor must modify the opinion. A qualified opinion applies when misstatements are material but not pervasive; an adverse opinion applies when they are both material and pervasive. Choice C is incorrect because once aggregate misstatements exceed materiality, the auditor cannot accept management''s assertion and must modify the opinion.', 'medium', 2),

-- Q23: medium / L2 — IT general control deficiency cascading to multiple application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Shore Banking Corp., the auditor determines that access controls over the general ledger application are deficient — three former employees retained system access for over 90 days after termination. This IT general control weakness affects automated controls in the revenue, payroll, and lending cycles. Under AU-C 265, the auditor should evaluate the severity based on:', '["Only the lending cycle because it represents the primary transaction risk in banking", "The single largest affected account balance among the three cycles", "The combined financial statement amounts processed by all applications relying on the deficient IT general control", "The number of former employees who retained access rather than the dollar amounts at risk"]'::jsonb, 2, 'Under AU-C 265.A8, severity evaluation considers the magnitude of potential misstatement that could result from the deficiency. When an IT general control weakness undermines multiple application controls, the auditor must consider all financial statement amounts exposed across the affected cycles. Choice A is incorrect because limiting the evaluation to one cycle ignores the pervasive nature of IT general control deficiencies affecting all dependent applications.', 'medium', 2),

-- Q24: easy / L1 — Definition of a control deficiency under AU-C 265
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["A control is designed, implemented, or operated in a way that does not allow management or employees to prevent or detect misstatements on a timely basis", "The auditor identifies any misstatement during substantive testing", "The entity has not implemented all five COSO internal control components", "Management overrides a control for a legitimate business purpose"]'::jsonb, 0, 'Under AU-C 265.07, a deficiency in internal control exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. Choice B is incorrect because finding a misstatement during substantive testing does not automatically indicate a control deficiency; misstatements can occur even when controls function properly.', 'easy', 1),

-- Q25: medium / L3 — Spillover effect of receiving deficiency on payables and COGS
(1, 'Misstatements and Control Deficiencies', 'At Evergreen Wholesale Distributors, the auditor identifies a significant deficiency in the shipping and receiving department''s process for matching goods received to purchase orders. The reconciliation failure means that inventory quantities may be misstated. The auditor should further analyze whether this deficiency also affects:', '["Revenue recognition only, since shipping errors affect sales transactions", "Only the warehouse operations, since the deficiency is limited to physical processes", "The payroll cycle, since shipping employees may be overstaffed", "Accounts payable and cost of goods sold, because unmatched receipts may cause errors in recorded liabilities and expense recognition"]'::jsonb, 3, 'Under AU-C 265.A8, the auditor evaluates the financial statement amounts and disclosures exposed to a deficiency. A failure in matching goods received to purchase orders affects not only inventory but also accounts payable (unrecorded or duplicate liabilities) and cost of goods sold (misstated expense when inventory is relieved). Choice A is incorrect because the receiving process primarily affects purchase-cycle accounts rather than the revenue cycle.', 'medium', 3),

-- Q26: easy / L1 — What must be attached to the management representation letter
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what must be attached to or included in the management representation letter?', '["The auditor''s working papers for each identified misstatement", "A list of all controls tested during the audit engagement", "A summary of uncorrected misstatements identified during the audit", "The engagement letter and fee arrangement"]'::jsonb, 2, 'Under AU-C 450.14, the auditor includes or attaches a summary of uncorrected misstatements to the written representation obtained from management. This ensures management formally acknowledges all identified but unadjusted items and represents that their effects are immaterial. Choice A is incorrect because audit working papers are the auditor''s documentation and are not shared with or attached to the management representation letter.', 'easy', 1),

-- Q27: medium / L2 — Prior-period uncorrected misstatement effect on current year
(1, 'Misstatements and Control Deficiencies', 'During the 2024 audit of Hartley Consumer Products, the auditor identified $35,000 in uncorrected overstatements of accounts receivable. These same receivables were collected in early 2025 and the original overstatement was not corrected. In the 2025 audit, the auditor should:', '["Evaluate whether the prior-period misstatement affects the current-period financial statements through its reversing or continuing effect", "Ignore the prior-period misstatement because it relates to a period already reported on", "Require management to restate the 2024 financial statements before continuing the 2025 audit", "Reduce 2025 materiality by $35,000 to compensate for the carryover misstatement"]'::jsonb, 0, 'Under AU-C 450.06, the auditor considers the effect of uncorrected misstatements from prior periods on the current period''s financial statements. A prior-year overstatement of receivables that reverses in the current year may understate current-year bad debt expense or overstate income if not properly accounted for. Choice B is incorrect because prior-period uncorrected misstatements can have continuing or reversing effects on current-period financial statements and must be evaluated.', 'medium', 2),

-- Q28: easy / L1 — Minimum documentation requirements for accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the auditor required to document regarding misstatements identified during the audit?', '["Only the total aggregate amount of all misstatements combined", "The amount below which misstatements are regarded as clearly trivial, all misstatements accumulated, and whether uncorrected misstatements are material", "The names of all employees responsible for each misstatement", "A detailed narrative describing the root cause of every misstatement"]'::jsonb, 1, 'Under AU-C 450.14, the auditor must document the amount below which misstatements are regarded as clearly trivial, all misstatements accumulated during the audit, and the conclusion about whether uncorrected misstatements are material individually or in aggregate. Choice A is incorrect because AU-C 450 requires documentation of each individual accumulated misstatement and the clearly trivial threshold, not merely a single aggregate total.', 'easy', 1),

-- Q29: medium / L3 — Directional impact of offsetting misstatements on audit conclusions
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Ridge Manufacturing, the auditor identifies five uncorrected misstatements: three overstate assets by $12,000, $8,000, and $15,000, while two understate assets by $9,000 and $11,000. Materiality is $40,000. When evaluating the aggregate effect, the auditor should recognize that:', '["The misstatements can be netted to $15,000, which is well below materiality", "Only the three overstatements totaling $35,000 are relevant because they move in the same direction", "Each misstatement should be evaluated independently without considering direction", "Both the gross overstatement of $35,000 and the net effect of $15,000 should be considered, as offsetting misstatements do not necessarily reduce audit risk"]'::jsonb, 3, 'Under AU-C 450.A7, the auditor considers both the gross and net effects of uncorrected misstatements. Simply netting misstatements may mask significant errors in individual accounts, and offsetting misstatements in different accounts may not reduce the risk of material misstatement in those accounts. Choice A is incorrect because netting alone may conceal material misstatements in individual financial statement line items, even when the net effect appears immaterial.', 'medium', 3),

-- Q30: hard / L3 — Complex analysis of layered IT and manual control deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Trident Financial Corp., the engagement team identifies three deficiencies: (1) the automated three-way match control for vendor invoices was disabled for two months during a system upgrade, (2) the manual compensating review implemented during the outage was performed by a staff accountant without proper authority, and (3) management did not monitor the timeline for restoring the automated control. The auditor should assess these deficiencies by recognizing that:', '["Each deficiency should be evaluated separately because they involve different control types", "Only the automated control failure matters because manual controls are inherently less reliable", "The three deficiencies represent a combination that collectively constitutes a material weakness because the compensating control was ineffective and management monitoring failed", "The deficiencies are mitigated because the automated control was eventually restored"]'::jsonb, 2, 'Under AU-C 265.A11, the auditor considers whether a combination of control deficiencies affecting the same significant account constitutes a significant deficiency or material weakness. Here, the primary control failed, the compensating control was ineffective due to the staff accountant lacking authority, and management oversight also failed — together representing a material weakness. Choice D is incorrect because eventual remediation does not retroactively mitigate the period during which no effective control operated.', 'hard', 3)
;

COMMIT;
